-- Mois 3 (jours 61 à 90) du programme HABITUDES_DEFIS_30J_FR_V1, version 1 : remplace la reprise des 30 textes du mois 1.
-- Textes validés par Dr Justin Tshims le 27/10/2026 (« C'est bon pour les textes du mois 3 »). Généré depuis
-- editorial/habitudes-defis/mois-3-fr-relecture.md. Aucune inscription n'avait encore atteint le jour 61 : les textes
-- déjà servis (jours 1 à 60) ne changent pas. Activités, défis et horaires inchangés.
do $$begin
 if exists(select 1 from seneve.enrollments e where e.programme_id='HABITUDES_DEFIS_30J_FR_V1' and e.etat='active'
  and seneve.hd_date_du_jour(e.enrollment_id,61)<=(now()at time zone 'Africa/Kinshasa')::date)then
  raise exception 'Une inscription a déjà atteint le jour 61 : publier une nouvelle version plutôt que modifier celle-ci';
 end if;
 if (select count(*)from seneve.contents where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour between 61 and 90 and numero_message=1)<>30 then
  raise exception 'Jours 61 à 90 incomplets';
 end if;
end$$;
update seneve.contents set titre=$t$Changer les causes$t$,principe=$t$Demander à Dieu de changer les causes, pas seulement les conséquences.$t$,theme=$t$Quelle cause, de ton côté, aimerais-tu que Dieu t'aide à changer ?$t$,texte_officiel=$t$Au début du livre, l'auteur raconte une nuit de dettes et de peur. Il priait alors : « Seigneur, fais quelque chose. Seigneur, envoie un miracle. » Plus tard, seul dans son salon, il a prié autrement : « Seigneur, je ne Te demande plus d'effacer les conséquences. Apprends-moi à changer les causes. » Il a ensuite remboursé ses dettes pendant trois ans, sans raccourci. Pense à une difficulté que tu portes. Au lieu de demander seulement qu'elle disparaisse, demande à Dieu de te montrer ce qui, de ton côté, peut changer.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 1, pages imprimées 13–16.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=61 and numero_message=1;
update seneve.contents set titre=$t$Habiter le Royaume, pas le visiter$t$,principe=$t$Laisser la foi du dimanche rejoindre le lundi.$t$,theme=$t$Dans quel lieu de ta semaine ta foi a-t-elle le plus de mal à se voir ?$t$,texte_officiel=$t$Paul écrit que Dieu « nous a transportés dans le royaume de Son Fils bien-aimé » (Colossiens 1:13). Le livre en tire une image : on ne visite pas le Royaume le dimanche, on y réside. Il décrit le citoyen du Royaume ainsi : « Son lundi ressemble à son dimanche. » Aujourd'hui, choisis un lieu ordinaire de ta journée, le marché, le bureau, la route ou la maison, et demande-toi comment ta foi peut s'y voir simplement.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 1, pages imprimées 17–18.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=62 and numero_message=1;
update seneve.contents set titre=$t$Religion ou Royaume$t$,principe=$t$Se situer honnêtement, une ligne à la fois.$t$,theme=$t$Quelle ligne du tableau aimerais-tu voir changer chez toi ?$t$,texte_officiel=$t$Le chapitre 1 propose un tableau en deux colonnes. D'un côté : prier mais décider seul, chercher la bénédiction, vivre dans l'urgence permanente. De l'autre : prier et attendre la direction de Dieu, chercher Sa volonté, garder la paix dans l'attente. Le livre invite à cocher honnêtement, ligne par ligne, la colonne qui te ressemble : « C'est entre toi et Dieu. » Fais-le aujourd'hui pour une seule ligne, sans te condamner. Si tu te reconnais dans la première colonne, ce n'est pas une fin : c'est l'endroit où commencer.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 1, page imprimée 21.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=63 and numero_message=1;
update seneve.contents set titre=$t$Consulter avant de signer$t$,principe=$t$Prendre le temps de prier avant une décision pressée.$t$,theme=$t$Quelle décision mérite quelques jours de prière avant d'y répondre ?$t$,texte_officiel=$t$Par le prophète Ésaïe, Dieu reprochait à Son peuple de prendre « des résolutions sans moi » (Ésaïe 30:1). Le livre raconte l'histoire de Marie-Claire, infirmière à Lagos, à qui l'on proposait un salaire doublé. Tout le monde la pressait de signer vite. Elle a pris trois jours pour prier, n'a pas trouvé la paix, et a refusé. Elle a dit plus tard : « Dieu prend soin de ceux qui Le consultent. » Avant ta prochaine décision importante, réserve un vrai temps de prière.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 1, pages imprimées 22–23.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=64 and numero_message=1;
update seneve.contents set titre=$t$Relire la semaine : le Roi plutôt que l'assistant$t$,principe=$t$Faire le point sur une semaine de consultation.$t$,theme=$t$Quelle décision de cette semaine as-tu pu présenter à Dieu ?$t$,texte_officiel=$t$Cette semaine a parlé de changer les causes plutôt que de seulement fuir les conséquences, de vivre sa foi le lundi comme le dimanche, de regarder honnêtement le tableau « religion ou Royaume » et de consulter Dieu avant de décider. Relis tes déclarations sans chercher de score. Remarque une décision où tu as pris le temps de prier, même brièvement. C'est souvent ainsi que les habitudes changent : par de petits moments répétés.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 1, pages imprimées 13–23 ; cahier Habitudes & Défis, section 9.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=65 and numero_message=1;
update seneve.contents set titre=$t$Un seul maître, moins d'inquiétude$t$,principe=$t$Relier la première place de Dieu à la paix intérieure.$t$,theme=$t$Quelle inquiétude veux-tu confier à Dieu aujourd'hui ?$t$,texte_officiel=$t$Le livre relit Matthieu 6 dans l'ordre. Jésus dit d'abord : « Vous ne pouvez servir Dieu et Mammon » (v. 24). Puis : « ne vous inquiétez pas » (v. 25). Puis : « Cherchez premièrement le Royaume de Dieu » (v. 33). Un seul maître, donc moins d'inquiétude, donc une seule priorité. Le livre ajoute : « Ton Père sait ce dont tu as besoin ». Aujourd'hui, quand une inquiétude revient, nomme-la devant Dieu au lieu de la garder pour toi.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 1, pages imprimées 24–25.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=66 and numero_message=1;
update seneve.contents set titre=$t$Chercher avant de courir$t$,principe=$t$Prendre un temps pour chercher Dieu dans une période difficile.$t$,theme=$t$Dans quelle situation es-tu tenté de courir avant de chercher ?$t$,texte_officiel=$t$Le livre raconte l'histoire de Patrice, à Nairobi, licencié alors qu'il avait une femme et trois enfants. Au lieu d'accepter n'importe quoi dans la panique, il a pris quarante jours pour chercher Dieu sérieusement, dans la prière. Le livre précise : « Je ne te promets pas que ton histoire sera identique ». Ce qui compte ici, c'est l'ordre : chercher avant de courir. Si tu traverses une période d'incertitude, réserve chaque jour un temps précis pour chercher Dieu, sans abandonner tes démarches.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 1, pages imprimées 26–27.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=67 and numero_message=1;
update seneve.contents set titre=$t$Le piège du « plus tard »$t$,principe=$t$Repérer ce qui a été remis à plus tard.$t$,theme=$t$Qu'as-tu remis à plus tard dans ta relation avec Dieu ?$t$,texte_officiel=$t$Le livre décrit la stratégie de Mammon : il ne demande pas de renier Dieu, seulement un report. « Occupe-toi d'abord de tes affaires. Stabilise-toi d'abord. Tu serviras Dieu après. » Il raconte l'histoire d'un imprimeur fidèle dont les livraisons ont peu à peu envahi les dimanches : « c'est temporaire », disait-il. Regarde aujourd'hui, sans t'accuser, ce que tu as remis à « plus tard » dans ta vie avec Dieu. Choisis une seule chose à reprendre cette semaine.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 1, pages imprimées 27–29.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=68 and numero_message=1;
update seneve.contents set titre=$t$Le foyer, premier territoire$t$,principe=$t$Laisser la foi se vivre à la maison.$t$,theme=$t$Quel petit geste de foi pourrais-tu partager chez toi cette semaine ?$t$,texte_officiel=$t$Le livre affirme que le Royaume s'exprime d'abord « dans ta maison ». Il cite le Deutéronome : parler de la Parole « quand tu seras dans ta maison, quand tu iras en voyage, quand tu te coucheras et quand tu te lèveras » (Deutéronome 6:7). La foi se transmet dans le quotidien, pas seulement dans les rassemblements. Aujourd'hui, partage un moment simple à la maison : une prière, un verset, un merci. Si tu vis seul ou seule, ce moment peut se vivre avec un proche, par un appel.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 1, pages imprimées 31–32.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=69 and numero_message=1;
update seneve.contents set titre=$t$Le pardon plutôt que les longs silences$t$,principe=$t$Faire un premier pas de paix avec un proche.$t$,theme=$t$Avec qui aimerais-tu faire un premier pas de paix ?$t$,texte_officiel=$t$Le livre décrit un foyer chrétien sain : il résout ses conflits « par la grâce et le pardon — pas par les cris ni les silences qui durent des semaines ». Il évoque des enfants qui voient leurs parents se demander pardon quand ils se sont blessés. Pense à une tension avec un proche, à la maison ou ailleurs. Aujourd'hui, fais un premier pas modeste : un mot, une excuse, une question posée calmement. Si la situation te met en danger, cherche plutôt de l'aide auprès d'une personne de confiance.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 1, page imprimée 32.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=70 and numero_message=1;
update seneve.contents set titre=$t$L'obéissance d'aujourd'hui$t$,principe=$t$Faire une chose que Dieu a déjà mise sur le cœur.$t$,theme=$t$Quelle étape, déjà sur ton cœur, peux-tu faire aujourd'hui ?$t$,texte_officiel=$t$Samuel dit à Saül : « L'obéissance vaut mieux que les sacrifices » (1 Samuel 15:22). Le livre observe que ceux qui avancent ne sont pas forcément les plus diplômés ni les mieux connectés : « Ce sont les plus obéissants. » Il ajoute une parole qui libère : « Tu n'as pas besoin d'être parfait pour commencer. » Et il termine le chapitre par une question : « qu'est-ce que Dieu t'a déjà demandé, que tu n'as pas encore fait ? » Choisis une petite étape, et fais-la aujourd'hui.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 1, pages imprimées 33–35.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=71 and numero_message=1;
update seneve.contents set titre=$t$Relire la semaine : l'ordre retrouvé$t$,principe=$t$Faire le point sur l'ordre, le foyer et l'obéissance.$t$,theme=$t$Qu'as-tu remis à sa place cette semaine ?$t$,texte_officiel=$t$Cette semaine a parlé de l'inquiétude confiée, de chercher avant de courir, du piège du « plus tard », du foyer, du pardon et de l'obéissance. Relis tes déclarations sans te juger. Remarque un moment où tu as remis quelque chose à sa place, même petit. Le chemin avance par des décisions simples et répétées, et reprendre après un oubli en fait partie.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 1, pages imprimées 24–35 ; cahier Habitudes & Défis, section 9.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=72 and numero_message=1;
update seneve.contents set titre=$t$Je change d'ordre$t$,principe=$t$Nommer devant Dieu un domaine à Lui remettre.$t$,theme=$t$Quel domaine veux-tu remettre à Dieu en premier ?$t$,texte_officiel=$t$Le chapitre 1 se termine par une prière : « Aujourd'hui, je change d'ordre. Je Te place en premier — dans mon temps, dans mon argent, dans mes décisions, dans mes relations. » L'engagement écrit qui suit invite à remettre à Dieu « le domaine précis où je Lui ai résisté jusqu'ici ». Prends un moment pour prier avec tes propres mots. Si tu le souhaites, écris ce domaine sur un papier qui reste à toi : SÉNEVÉ ne te le demande pas.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 1, pages imprimées 36–37.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=73 and numero_message=1;
update seneve.contents set titre=$t$Le dernier domaine confié$t$,principe=$t$Regarder avec calme sa relation à l'argent.$t$,theme=$t$Que ressens-tu quand on parle d'argent à l'église, et pourquoi ?$t$,texte_officiel=$t$Le chapitre 2 commence par une observation : « Le portefeuille est le dernier domaine qu'un homme abandonne à Dieu. » On peut renoncer à beaucoup de choses et garder son argent fermé à Dieu. L'auteur reconnaît aussi que des abus commis au nom de la dîme ont créé de la méfiance. Il précise qu'il ne parle pas de ce que l'église veut, mais de ce que Dieu a établi. Aujourd'hui, regarde simplement si ton argent fait partie de ce que tu confies à Dieu dans la prière.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 2, pages imprimées 38–39.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=74 and numero_message=1;
update seneve.contents set titre=$t$Reconnaître d'où vient la victoire$t$,principe=$t$Relier ce que l'on reçoit à Celui qui le donne.$t$,theme=$t$Quelle réussite récente veux-tu reconnaître comme un don de Dieu ?$t$,texte_officiel=$t$Le livre rappelle qu'Abraham a donné la dîme à Melchisédek après sa victoire (Genèse 14), quatre siècles avant la Loi de Moïse. Personne ne le lui avait commandé. Le livre y voit « la réponse naturelle d'un homme qui comprend que sa victoire vient de Dieu ». Pense à une réussite récente, petite ou grande : un examen, un travail terminé, un problème réglé, une aide reçue. Remercie Dieu précisément pour elle aujourd'hui.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 2, pages imprimées 41–42.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=75 and numero_message=1;
update seneve.contents set titre=$t$Un vœu né de la grâce$t$,principe=$t$Donner par reconnaissance plutôt que par contrainte.$t$,theme=$t$Quel souvenir de la fidélité de Dieu te rend reconnaissant ou reconnaissante ?$t$,texte_officiel=$t$À Béthel, après sa vision de l'échelle, Jacob fait ce vœu : « Je te donnerai la dîme de tout ce que tu me donneras » (Genèse 28:22). Le livre souligne qu'aucun commandement écrit ne l'y obligeait : « Juste un cœur touché par la grâce. » Le don vient ici après une rencontre avec Dieu. Aujourd'hui, avant de penser à ce que tu donnes, prends le temps de te souvenir de ce que Dieu a fait pour toi.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 2, page imprimée 42.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=76 and numero_message=1;
update seneve.contents set titre=$t$Sans négliger la justice$t$,principe=$t$Garder ensemble le don et la justice du cœur.$t$,theme=$t$Où la justice et la miséricorde te sont-elles demandées cette semaine ?$t$,texte_officiel=$t$Le livre cite Matthieu 23:23, où Jésus parle de la dîme et ajoute : « C'est là ce qu'il fallait pratiquer, sans négliger les autres choses. » Dans ce passage, ces autres choses sont la justice, la miséricorde et la fidélité. Pour le livre, la dîme n'est pas un impôt religieux mais un acte de justice. Donner ne remplace jamais la manière dont on traite les autres. Aujourd'hui, pose un geste de justice ou de miséricorde envers quelqu'un.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 2, pages imprimées 42–43.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=77 and numero_message=1;
update seneve.contents set titre=$t$Prier pour ceux qui te nourrissent$t$,principe=$t$Reconnaître ceux qui veillent sur ta vie spirituelle.$t$,theme=$t$Qui nourrit ton âme en ce moment ?$t$,texte_officiel=$t$Le livre rappelle que la dîme soutenait autrefois les Lévites, consacrés au service de Dieu (Nombres 18:21), et cite Paul : « le Seigneur a ordonné à ceux qui annoncent l'Évangile de vivre de l'Évangile » (1 Corinthiens 9:14). Il pose une question pratique : « Qui nourrit ton âme ? » Il conseille aussi la sagesse : se relier à un ministère fidèle à la Parole. Aujourd'hui, prie pour une personne qui veille sur toi dans la prière, et remercie-la si tu le peux.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 2, pages imprimées 44–45.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=78 and numero_message=1;
update seneve.contents set titre=$t$Relire la semaine : donner avec reconnaissance$t$,principe=$t$Faire le point sur la reconnaissance et le don.$t$,theme=$t$Qu'est-ce qui a nourri ta reconnaissance cette semaine ?$t$,texte_officiel=$t$Cette semaine a parlé du chemin vers le don : remettre à Dieu son ordre et son argent, reconnaître d'où vient la victoire, donner par reconnaissance, garder la justice et prier pour ceux qui te nourrissent. Relis tes déclarations sans te comparer à personne. Aucun montant n'est attendu de toi ici. Remarque surtout si ta manière de regarder ce que tu reçois a changé.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitres 1 et 2, pages imprimées 36–45 ; cahier Habitudes & Défis, section 9.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=79 and numero_message=1;
update seneve.contents set titre=$t$La première part dans le manque$t$,principe=$t$Réfléchir à la confiance quand les ressources sont faibles.$t$,theme=$t$Dans quel manque as-tu le plus de mal à faire confiance à Dieu ?$t$,texte_officiel=$t$Le livre relit l'histoire de la veuve de Sarepta (1 Rois 17). Elle n'avait plus qu'une poignée de farine et un peu d'huile, et Élie lui demanda de préparer d'abord pour lui. Elle obéit, et la Parole dit : « La farine qui était dans le pot ne manqua point ». Pour le livre, la pénurie est souvent le lieu où la foi se démontre. Ce récit ne fixe aucun montant pour toi. Il t'invite à regarder où tu fais confiance à Dieu quand tu as peu.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 2, pages imprimées 46–47.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=80 and numero_message=1;
update seneve.contents set titre=$t$Ne plus avoir peur de manquer$t$,principe=$t$Recevoir la paix avant toute autre chose.$t$,theme=$t$Quelle peur liée à l'argent veux-tu confier à Dieu ?$t$,texte_officiel=$t$Le livre raconte l'histoire de Cécile, à Kinshasa, qui mit de côté sa dîme sur un don de cent dollars, dans une période très dure. Elle dit plus tard : « Je ne dis pas que la dîme a causé le contrat. » Ce qu'elle retient, c'est autre chose : « j'ai arrêté d'avoir peur de manquer. » Le livre appelle cela la première bénédiction : être libéré de la peur. Aujourd'hui, nomme devant Dieu une peur liée à l'argent et demande-Lui Sa paix.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 2, pages imprimées 47–48.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=81 and numero_message=1;
update seneve.contents set titre=$t$Ce que Dieu regarde$t$,principe=$t$Comprendre que Dieu voit le cœur plus que la somme.$t$,theme=$t$Qu'est-ce que tu as du mal à lâcher en ce moment ?$t$,texte_officiel=$t$Au temple, Jésus regarde des riches déposer de grandes sommes, puis une veuve qui donne deux petites pièces. Il dit : « Cette pauvre veuve a donné plus que tous. » Le livre explique : les riches avaient donné de leur superflu, elle avait donné ce qu'elle avait pour vivre. « Il voit ce que tu as gardé, pas seulement ce que tu as donné. » Cette parole n'est pas un reproche. Elle invite à regarder avec honnêteté ce que tu retiens : de l'argent, du temps ou de l'attention.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 2, pages imprimées 48–49.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=82 and numero_message=1;
update seneve.contents set titre=$t$La foi, pas la loterie$t$,principe=$t$Donner sans chercher à obliger Dieu.$t$,theme=$t$Qu'est-ce qui te pousse à donner, quand tu donnes ?$t$,texte_officiel=$t$Le livre met en garde contre une manière de donner comme on joue à la loterie : « J'ai semé mille dollars, Dieu me doit dix mille. » Sa réponse est claire : « Tu n'achètes pas Dieu. » On ne L'oblige pas ; on aligne sa vie sur Ses principes et on fait confiance à Sa fidélité. Si quelqu'un te promet un gain en échange d'un don, souviens-toi de cette page. Donner reste un acte de confiance et d'amour, jamais un marché.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 2, page imprimée 51.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=83 and numero_message=1;
update seneve.contents set titre=$t$Ce qui disparaît avant le quinze$t$,principe=$t$Observer les fuites et confier ce qui reste.$t$,theme=$t$Quel imprévu revient souvent dans ton budget ?$t$,texte_officiel=$t$Malachie 3:11 parle de « celui qui dévore ». Le livre l'applique à une expérience connue : « tu reçois ton salaire, et avant le quinze du mois, tout a disparu ». Il raconte l'histoire de Thomas, restaurateur, qui a décidé de donner à Dieu en premier et dit : « il semble y avoir une protection sur ce qui reste. » Ce récit ne promet pas qu'aucun imprévu n'arrivera. Aujourd'hui, confie à Dieu ce que tu as, et repère une dépense imprévue qui revient souvent, pour mieux t'y préparer.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 2, pages imprimées 51–53.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=84 and numero_message=1;
update seneve.contents set titre=$t$Une proportion, pas un montant$t$,principe=$t$Comprendre que la fidélité ne dépend pas de la somme.$t$,theme=$t$Qu'est-ce qui rend la fidélité possible, même avec peu ?$t$,texte_officiel=$t$À l'objection « Je n'ai pas assez pour donner la dîme », le livre répond : « La dîme n'est pas un montant — c'est une proportion. » Dix pour cent de mille francs, c'est cent francs ; de cinq cents francs, c'est cinquante. Il conclut : « La fidélité ne dépend pas du montant. » Si tu pratiques la dîme, le simulateur facultatif du module peut t'aider à faire ce calcul ; il n'enregistre rien et ne déclenche aucun paiement.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 2, pages imprimées 54–55.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=85 and numero_message=1;
update seneve.contents set titre=$t$Relire la semaine : la confiance$t$,principe=$t$Faire le point sur la confiance et la peur de manquer.$t$,theme=$t$Quelle peur s'est un peu apaisée cette semaine ?$t$,texte_officiel=$t$Cette semaine a parlé de la confiance dans le manque, de la peur de manquer, de ce que Dieu regarde, du refus de marchander avec Lui, des fuites d'argent et de la fidélité qui ne dépend pas du montant. Relis ce que tu as vécu sans te juger. Le livre rappelle qu'on ne peut pas obliger Dieu, mais qu'on peut Lui faire confiance. Note une peur qui s'est un peu apaisée, ou une autre qui demande encore du temps.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 2, pages imprimées 46–55 ; cahier Habitudes & Défis, section 9.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=86 and numero_message=1;
update seneve.contents set titre=$t$Quand l'exemple des autres déçoit$t$,principe=$t$Ne pas laisser l'abus des uns décider à ta place.$t$,theme=$t$Quelle déception a pu freiner ta confiance ?$t$,texte_officiel=$t$Le livre entend l'objection : « Les pasteurs s'enrichissent avec nos dîmes. » Il répond : « Certains, oui. » Puis il ajoute que l'abus des uns n'annule pas le principe, comme on ne cesse pas de se marier parce que certains mariages échouent. Il conseille de chercher un ministère fidèle à la Parole. Si une déception te pèse, parle-en à Dieu honnêtement, et, si c'est utile, à une personne de confiance.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 2, page imprimée 55.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=87 and numero_message=1;
update seneve.contents set titre=$t$Une alliance, pas une transaction$t$,principe=$t$Regarder la fidélité sur la durée.$t$,theme=$t$Où as-tu besoin de patience en ce moment ?$t$,texte_officiel=$t$À l'objection « Je ne vois pas de résultats immédiats », le livre répond : « La dîme est une alliance, pas une transaction. » Une alliance se vérifie sur des années, pas sur des semaines. Il ajoute avec humour : « Les comptables de Dieu ne font pas leurs bilans à la fin du mois. » Cette patience vaut aussi pour tes habitudes : un jour manqué ne défait pas un chemin. Reprends simplement là où tu en es.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 2, page imprimée 55.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=88 and numero_message=1;
update seneve.contents set titre=$t$Tout est un prêt$t$,principe=$t$Recevoir ce que l'on a comme confié par Dieu.$t$,theme=$t$Quelles trois choses t'ont été confiées ?$t$,texte_officiel=$t$La prière du chapitre 2 dit : « Mon salaire, mes bénéfices, ma santé, mon intelligence — tout est un prêt de Ta main. » Regarder ce qu'on a comme un prêt change la manière de le gérer : avec soin, avec gratitude et sans peur. Ce soir, pendant ta gratitude, nomme trois choses qui t'ont été confiées et demande à Dieu la sagesse pour en prendre soin.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 2, pages imprimées 56–57.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=89 and numero_message=1;
update seneve.contents set titre=$t$Là où est ton trésor$t$,principe=$t$Faire un bilan paisible du mois et choisir un pas.$t$,theme=$t$Quel pas veux-tu garder pour le mois prochain ?$t$,texte_officiel=$t$Le chapitre 2 se termine par cette phrase : « Là où ton trésor se trouve, ton cœur finit toujours par habiter. » Ce mois a parlé de la première place de Dieu, de l'ordre, du foyer, de l'obéissance et du don. Relis tes bilans de semaine et choisis un seul pas pour le mois prochain. Ton bilan ne mesure ni ta foi ni ta valeur. Tes habitudes quotidiennes continuent, et tu peux adapter tes horaires à tout moment.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 2, page imprimée 57.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=90 and numero_message=1;
update seneve.programme_versions set valide_par=valide_par||' ; mois 3 (jours 61 à 90) validé le 27/10/2026'
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and valide_par not like '%mois 3%';
